from collections import OrderedDict


class LRUCache:
    """A fixed-capacity cache that evicts the least recently used entry.

    Both `get` and `put` count as uses, so touching a key moves it to the
    most-recent end of the underlying OrderedDict.
    """

    __slots__ = ("capacity", "_data")

    def __init__(self, capacity):
        if capacity <= 0:
            raise ValueError("capacity must be positive")
        self.capacity = capacity
        self._data = OrderedDict()

    def get(self, key, default=None):
        """Return the value for `key`, marking it as recently used."""
        if key not in self._data:
            return default
        self._data.move_to_end(key)
        return self._data[key]

    def put(self, key, value):
        """Insert or update `key`, evicting the oldest entry if full."""
        if key in self._data:
            self._data.move_to_end(key)
        self._data[key] = value
        if len(self._data) > self.capacity:
            self._data.popitem(last=False)

    def __contains__(self, key):
        # Membership is a peek, not a use: it does not reorder anything.
        return key in self._data

    def __len__(self):
        return len(self._data)

    def __repr__(self):
        items = ", ".join(f"{k!r}: {v!r}" for k, v in self._data.items())
        return f"LRUCache(capacity={self.capacity}, {{{items}}})"
